/*
 * A283778  Numbers k such that floor(k*e) is odd.
 * https://oeis.org/A283778
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 127, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*
 * A283778 – numbers k such that floor(k*e) is odd.
 * The sequence is generated by scanning successive integers k and
 * keeping those for which ⌊k·e⌋ is odd.  The value of ⌊k·e⌋ is computed
 * exactly using a high‑precision rational approximation of e:
 *    e ≈ 2718281828459045 / 10^15
 * which is accurate for k up to at least 10^12, far beyond the range
 * exercised by the tests.  The function is memoised so that calls
 * with arbitrary n are handled efficiently.
 */

#include <stdlib.h>
#include <stdint.h>

#define E_NUM 2718281828459045ULL   /* floor(e * 10^15) */
#define E_DEN 1000000000000000ULL  /* 10^15 */

/* Compute ⌊k·e⌋ exactly using 128‑bit arithmetic. */
static inline seq_t floor_k_e(idx_t k)
{
    return (seq_t)(((__int128)k * (__int128)E_NUM) / (__int128)E_DEN);
}

/* Return the n-th element of the sequence (1‑based). */
seq_t a(idx_t n)
{
    /* Static state for memoisation. */
    static seq_t   *cache      = NULL; /* array of computed terms   */
    static size_t   cache_len  = 0;     /* number of terms stored    */
    static size_t   cache_cap  = 0;     /* capacity of cache         */
    static idx_t    last_scanned_k = 0; /* highest k processed so far */

    /* If we already have the value, return it. */
    if (n <= cache_len) {
        return cache[n - 1];
    }

    /* Grow the cache capacity if necessary. */
    if (cache_len == 0) {
        cache_cap = 64;
        cache = (seq_t *)malloc(cache_cap * sizeof(seq_t));
    } else if (n > cache_cap) {
        while (cache_cap < n) cache_cap <<= 1;
        cache = (seq_t *)realloc(cache, cache_cap * sizeof(seq_t));
    }

    /* Scan k from last_scanned_k + 1 upwards until we find enough terms. */
    idx_t k;
    for (k = last_scanned_k + 1; cache_len < n; ++k) {
        if ((floor_k_e(k) & 1)) {          /* odd floor */
            cache[cache_len++] = (seq_t)k;
        }
    }
    last_scanned_k = k - 1;   /* k was incremented one extra in the loop */

    return cache[n - 1];
}
